const keyword = String(tobub.params.keyword ?? '').trim();
const requestedCount = Number(tobub.params.count ?? 50);
if (!keyword || keyword.length > 100) throw new Error('keyword must contain 1 to 100 characters.');
if (!Number.isInteger(requestedCount) || requestedCount < 1 || requestedCount > 100) {
  throw new Error('count must be an integer from 1 to 100.');
}

const itemSelector = '[data-test-card-id="undefined-default"]';
const records = [];
const seenIds = new Set();
const seenPageFingerprints = new Set();
let pagesVisited = 0;
let duplicateCount = 0;
let failedCount = 0;
let failedSaveCount = 0;
let collected = 0;
let persisted = 0;
let completionReason = 'pagination_terminal';
let sourceUrl = '';

const existingPages = await tobub.browser.pages();
const existingPageIds = new Set(existingPages.map(page => page.id));
await tobub.atoms.navigate({ url: 'https://www.toutiao.com', waitUntil: 'domcontentloaded' });
await tobub.atoms.waitFor([1200, 2000]);
const homePage = await tobub.browser.current();
await tobub.atoms.fill(
  { role: 'textbox', name: '搜索', value: keyword },
  { page: homePage, timeout: 10000 }
);
await tobub.atoms.click(
  { role: 'button', name: '搜索', exact: true },
  { page: homePage, timeout: 10000 }
);

let searchPage = null;
for (let attempt = 0; attempt < 20; attempt++) {
  await tobub.atoms.waitFor([400, 700]);
  const openPages = await tobub.browser.pages();
  searchPage = openPages.find(page => {
    if (existingPageIds.has(page.id)) return false;
    try {
      const parsed = new URL(page.url);
      return parsed.hostname === 'so.toutiao.com'
        && parsed.pathname.includes('/search')
        && parsed.searchParams.get('keyword') === keyword;
    } catch {
      return false;
    }
  }) || null;
  if (searchPage) break;
}
if (!searchPage) {
  throw new Error('首页搜索没有打开包含当前关键词的新搜索标签页；未改用 URL 直达。');
}
await tobub.browser.bringToFront(searchPage);

await tobub.atoms.click(
  { role: 'link', name: '资讯', exact: true },
  { page: searchPage, timeout: 10000 }
);
await tobub.atoms.waitFor([1400, 2200], { page: searchPage });

async function readLocation(pageRef) {
  const result = await tobub.atoms.evaluate({
    expression: '() => ({ href: location.href, title: document.title, keyword: new URL(location.href).searchParams.get("keyword") || "" })'
  }, { page: pageRef });
  return result.value ?? {};
}

const infoLocation = await readLocation(searchPage);
if (!String(infoLocation.href ?? '').includes('pd=information')) {
  throw new Error('搜索页未切换到“资讯”结果；未开始采集。当前页面：' + String(infoLocation.href ?? 'unknown'));
}
sourceUrl = String(infoLocation.href);

const ready = await tobub.atoms.condition(
  { type: 'count', selector: itemSelector, comparison: 'gte', value: 1, pollInterval: 250, throwOnTimeout: false },
  { timeout: 15000, page: searchPage }
);
if (!ready.satisfied) {
  const bodyState = await tobub.atoms.evaluate({
    expression: '() => ({ text: (document.body?.innerText || "").slice(0, 2000), href: location.href })'
  }, { page: searchPage });
  const bodyText = String(bodyState.value?.text ?? '');
  if (/没有找到|暂无相关|无相关结果|没有相关内容|未找到相关/i.test(bodyText)) {
    return {
      status: 'empty',
      keyword,
      requested: requestedCount,
      collected: 0,
      persisted: 0,
      database_observations: [],
      pages_visited: 1,
      duplicates: 0,
      failed: 0,
      failed_saves: 0,
      completion_reason: 'no_results',
      source_url: sourceUrl,
      records: []
    };
  }
  throw new Error('“资讯”页等待 15 秒仍没有可见结果卡片；页面可能被拦截或结构已变化。');
}

function readPageInBrowser() {
  const selector = '[data-test-card-id="undefined-default"]';
  const cards = Array.from(document.querySelectorAll(selector))
    .filter(card => card.getClientRects().length > 0);
  const results = cards.map(card => {
    let extra = {};
    try {
      extra = JSON.parse(card.querySelector('[data-log-extra]')?.getAttribute('data-log-extra') || '{}');
    } catch {}
    const titleLink = card.querySelector('.cs-header a[href]');
    const content = card.querySelector('.cs-card-content');
    const summaryNode = content?.querySelector('.cs-text.align-items-center .flex-1.text-default.text-m.text-regular');
    const source = card.querySelector('.cs-source-content');
    const sourceSpans = source
      ? Array.from(source.querySelectorAll('span.text-ellipsis'))
          .map(node => (node.innerText || '').trim())
          .filter(Boolean)
      : [];
    let targetUrl = titleLink?.href || '';
    for (let hop = 0; hop < 4; hop++) {
      try {
        const parsed = new URL(targetUrl, location.href);
        const inner = parsed.searchParams.get('url');
        if (!inner || !parsed.pathname.includes('/search/jump')) {
          targetUrl = parsed.toString();
          break;
        }
        targetUrl = inner;
      } catch {
        break;
      }
    }
    if (targetUrl.startsWith('http://www.toutiao.com/')) targetUrl = targetUrl.replace('http://', 'https://');
    const articleMatch = targetUrl.match(/\/a(\d+)/);
    const id = String(extra.group_id || extra.item_id || extra.search_result_id || (articleMatch ? articleMatch[1] : '')).trim();
    return {
      id,
      title: (titleLink?.innerText || '').trim(),
      summary: (summaryNode?.innerText || '').trim().slice(0, 800),
      url: targetUrl,
      author: sourceSpans[0] || '',
      published_at: sourceSpans.length > 1 ? sourceSpans[sourceSpans.length - 1] : '',
      comments_source: (card.innerText || '').trim()
    };
  });
  const nextLink = Array.from(document.querySelectorAll('a[href]'))
    .find(link => (link.innerText || '').trim() === '下一页' && link.getClientRects().length > 0);
  const query = new URL(location.href).searchParams;
  const pageNumber = Number(query.get('page_num') || 0);
  return {
    url: location.href,
    page_number: Number.isFinite(pageNumber) ? pageNumber : 0,
    results,
    next_url: nextLink?.href || '',
    next_text: nextLink ? (nextLink.innerText || '').trim() : ''
  };
}

async function readPage() {
  const result = await tobub.atoms.evaluate({
    expression: '(' + readPageInBrowser.toString() + ')()'
  }, { page: searchPage });
  return result.value ?? {};
}

function parseCommentCount(text) {
  const lines = String(text || '').split('\n').map(line => line.trim()).filter(Boolean);
  for (const line of lines) {
    const commentIndex = line.indexOf('评论');
    if (commentIndex < 0) continue;
    const before = line.slice(0, commentIndex).trim();
    const after = line.slice(commentIndex + '评论'.length).trim();
    const match = before.match(/([\d,.]+)\s*(万|w|W)?$/) || after.match(/^([\d,.]+)\s*(万|w|W)?/);
    if (!match) continue;
    const base = Number(match[1].replace(/,/g, ''));
    if (!Number.isFinite(base)) continue;
    const multiplier = match[2] && /^(万|w|W)$/.test(match[2]) ? 10000 : 1;
    return Math.round(base * multiplier);
  }
  return null;
}

let page = await readPage();
const maxPages = 50;
for (let pageIndex = 0; pageIndex < maxPages && persisted < requestedCount; pageIndex++) {
  const pageUrl = String(page.url ?? '');
  if (!pageUrl) {
    completionReason = 'page_error';
    break;
  }
  const fingerprint = page.results.map(item => String(item.id || item.title || '')).join('|');
  if (!fingerprint || seenPageFingerprints.has(fingerprint)) {
    completionReason = pagesVisited === 0 ? 'no_results' : 'stalled';
    break;
  }
  seenPageFingerprints.add(fingerprint);
  pagesVisited++;

  for (const item of page.results) {
    if (persisted >= requestedCount) break;
    const id = String(item.id || '').trim();
    const title = String(item.title || '').trim();
    const articleUrl = String(item.url || '').trim();
    if (!id || !title || !/^https?:\/\//i.test(articleUrl)) {
      failedCount++;
      continue;
    }
    if (seenIds.has(id)) {
      duplicateCount++;
      continue;
    }
    seenIds.add(id);
    collected++;

    const record = {
      id,
      title,
      summary: String(item.summary || ''),
      url: articleUrl,
      author: String(item.author || ''),
      comment_count: parseCommentCount(item.comments_source),
      published_at: String(item.published_at || ''),
      page_number: Number(page.page_number || 0) + 1
    };
    try {
      const saved = await tobub.db.saveContent({
        platform: 'toutiao',
        contentType: 'article',
        externalId: record.id,
        title: record.title,
        summary: record.summary,
        url: record.url,
        metadata: {
          keyword,
          author: record.author,
          commentCount: record.comment_count,
          publishedAt: record.published_at,
          pageNumber: record.page_number,
          sourceUrl
        },
        rawData: record,
        observationSource: 'toutiao-search',
        observationMeta: {
          keyword,
          pageNumber: record.page_number,
          sourceUrl
        }
      });
      if (!saved || !saved.observationId || !saved.contentItemId) {
        throw new Error('tobub.db.saveContent did not return a content observation.');
      }
      persisted++;
      records.push({
        ...record,
        content_item_id: saved.contentItemId,
        observation_id: saved.observationId
      });
    } catch (error) {
      failedCount++;
      failedSaveCount++;
    }
  }

  if (persisted >= requestedCount) {
    completionReason = 'requested_count';
    break;
  }

  const nextUrl = String(page.next_url || '');
  if (!nextUrl) {
    completionReason = 'pagination_terminal';
    break;
  }

  const oldPageNumber = Number(page.page_number || 0);
  const nextUrlObject = new URL(nextUrl, pageUrl);
  const expectedPageNumber = Number(nextUrlObject.searchParams.get('page_num'));
  if (!Number.isFinite(expectedPageNumber) || expectedPageNumber <= oldPageNumber) {
    completionReason = 'stalled';
    break;
  }

  let clickSucceeded = false;
  try {
    await tobub.atoms.click(
      { role: 'link', name: '下一页', exact: true },
      { page: searchPage, timeout: 8000 }
    );
    clickSucceeded = true;
  } catch {
    completionReason = 'stalled';
    break;
  }

  let advancedPage = null;
  for (let waitIndex = 0; waitIndex < 24; waitIndex++) {
    await tobub.atoms.waitFor([500, 800], { page: searchPage });
    const candidate = await readPage();
    const candidateFingerprint = candidate.results
      .map(item => String(item.id || item.title || ''))
      .join('|');
    const hasPageAdvanced = Number(candidate.page_number) === expectedPageNumber;
    const hasNewPageContent = candidateFingerprint && candidateFingerprint !== fingerprint;
    if (clickSucceeded && hasPageAdvanced && hasNewPageContent) {
      advancedPage = candidate;
      break;
    }
  }
  if (!advancedPage) {
    completionReason = 'stalled';
    break;
  }
  page = advancedPage;
}

if (persisted < requestedCount && pagesVisited >= maxPages) completionReason = 'page_limit';
if (failedSaveCount > 0 && completionReason === 'requested_count') completionReason = 'database_error';
const status = persisted === requestedCount && failedCount === 0 ? 'ok' : persisted > 0 ? 'partial' : 'empty';
return {
  status,
  keyword,
  requested: requestedCount,
  collected,
  persisted,
  database_observations: records.map(record => record.observation_id),
  pages_visited: pagesVisited,
  duplicates: duplicateCount,
  failed: failedCount,
  failed_saves: failedSaveCount,
  completion_reason: completionReason,
  source_url: sourceUrl,
  records
};
